# Batch 3: Motivation, Peace, Relationships, Self-Love, Study, Success, Wisdom, Work

BATCH3_QUOTES = {
    "Motivation": [
        {"id": "q_1", "text": "Your mindset shapes your day. Choose wonder over worry, intention over habit.", "author": "Stillwords", "isOriginal": True, "isFeatured": True, "moods": "Motivated,Focused,Confident", "situations": "Morning,Before Work,Starting Over"},
        {"id": "q_27", "text": "Big mountains are not climbed in sudden leaps. They are climbed by a person who took twenty thousand ordinary, unglamorous steps without stopping.", "author": "Stillwords", "isOriginal": True, "isFeatured": True, "moods": "Determined,Motivated", "situations": "Morning,Before Work,Workout"},
        {"id": "q_moti_1", "text": "Do not wait for the perfect moment. Take the messy, imperfect moment in front of you and make it honest.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Motivated", "situations": "Starting Over,Before Work"},
        {"id": "q_moti_2", "text": "The secret to getting ahead is simply getting started while the crowd is still debating the weather.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Confident", "situations": "Morning,Before Work"},
        {"id": "q_moti_3", "text": "A tiny candle does not apologize for its small flame; it simply lights the dark corridor.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Confident", "situations": "Need Confidence,Difficult Day"},
        {"id": "q_moti_4", "text": "Energy flows where attention goes. Point your focus toward what builds life and watch strength return.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Motivated", "situations": "Before Work,Study Time"},
        {"id": "q_moti_5", "text": "When the goal feels impossibly far, shorten your gaze to the next thirty minutes. Win those thirty minutes.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Difficult Day,Study Time"},
        {"id": "q_moti_6", "text": "You do not need an audience to do magnificent work. The stars shine in empty space without applause.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Confident", "situations": "Before Work,Study Time"},
        {"id": "q_moti_7", "text": "The hardest part of the journey is always crossing the threshold of your own front door. Step out.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Determined", "situations": "Morning,Workout"},
        {"id": "q_moti_8", "text": "Let your hunger for honest craftsmanship outweigh your fear of falling short.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Before Work,Study Time"},
        {"id": "q_moti_9", "text": "Every morning you wake up, life is whispering: 'Here is another chance to build something true.'", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Motivated", "situations": "Morning,Starting Over"},
        {"id": "q_moti_10", "text": "Do not let small setbacks trick you into abandoning long-term dreams. Ships adjust their rudders all voyage long.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Hopeful", "situations": "Difficult Day,Starting Over"},
        {"id": "q_moti_11", "text": "Bring your whole heart to the table today. Half-hearted striving tires you twice as fast.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Focused", "situations": "Morning,Before Work"},
        {"id": "q_moti_12", "text": "The road forward will appear under your feet once you begin walking with conviction.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Hopeful", "situations": "Starting Over,Need Confidence"},
        {"id": "q_moti_13", "text": "Focus on being faithful to the task, not famous for the result.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Focused", "situations": "Before Work,Study Time"},
        {"id": "q_moti_14", "text": "There is a profound joy in sweating for a purpose you believe in with your whole soul.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Happy", "situations": "Workout,Before Work"},
        {"id": "q_moti_15", "text": "Do not measure your day by the trophies on the shelf, but by the quiet grit in your heart.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Confident", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_moti_16", "text": "The spark of inspiration is a match; your daily habit is the dry firewood that keeps the flame alive.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Focused", "situations": "Before Work,Study Time"},
        {"id": "q_moti_17", "text": "Step into the arena. It is far better to dare and get dust on your brow than to sit in cynical safety.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Confident", "situations": "Need Confidence,Before Work"},
        {"id": "q_moti_18", "text": "When you want to give up, remember why you sacrificed comfort to stand here in the first place.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Focused", "situations": "Difficult Day,Workout"},
        {"id": "q_moti_19", "text": "A good start is half the battle won. Clear the desk, pour the water, and sit down.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Motivated", "situations": "Morning,Study Time"},
        {"id": "q_moti_20", "text": "Let your enthusiasm be contagious. A motivated spirit warms every room it enters.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Motivated", "situations": "Morning,Before Work"},
        {"id": "q_moti_21", "text": "Do not let the fatigue of dusk rob you of the conviction you held at dawn.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Calm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_moti_22", "text": "You are capable of doing hard things quietly and well.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Determined", "situations": "Difficult Day,Workout"},
        {"id": "q_moti_23", "text": "Plant your feet firmly and meet the day. You were made for this hour.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Confident", "situations": "Morning,Before Work"},
        {"id": "q_moti_24", "text": "Work with the steady rhythm of a blacksmith hammer. Steady strikes shape hot iron.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Before Work,Study Time"},
        {"id": "q_moti_25", "text": "Do not surrender your morning energy to minor trifles. Aim straight for the bullseye.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Motivated", "situations": "Morning,Before Work"},
        {"id": "q_moti_26", "text": "Believe in the quiet power of your daily contribution. Drops of water hollow out the hardest rock.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Calm", "situations": "Study Time,Before Work"},
        {"id": "q_moti_27", "text": "The wind will not always be behind you. Learn to tack into the headwind.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Confident", "situations": "Difficult Day,Workout"},
        {"id": "q_moti_28", "text": "Show up today with wholehearted presence. That is where miracles begin.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Motivated", "situations": "Morning,Before Work"}
    ],

    "Peace": [
        {"id": "q_8", "text": "Let the day's unresolved questions rest on the nightstand. They will look smaller in tomorrow's sun, and your tired heart needs sleep more than solutions.", "author": "Stillwords", "isOriginal": True, "isFeatured": True, "moods": "Calm,Peace", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_peace_1", "text": "Peace is not the absence of trouble; it is the presence of quiet stillness in the midst of the storm.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Difficult Day,Morning"},
        {"id": "q_peace_2", "text": "Lay down your arguments at twilight. The day has finished, and sleep asks only for surrender.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_peace_3", "text": "Listen to the quiet breathing of the house while the world outside sleeps.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Before Sleep,Morning"},
        {"id": "q_peace_4", "text": "There is a profound stillness that comes when you stop trying to control what was never yours to govern.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_peace_5", "text": "Let the cool evening breeze carry away the heat of afternoon frustrations.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Relieved", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_peace_6", "text": "A cup of warm chamomile tea, an open book, and rain against the window: that is peace in human form.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Happy", "situations": "Before Sleep,Study Time"},
        {"id": "q_peace_7", "text": "You do not need to attend every argument you are invited to. Preserve your tranquility.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Calm", "situations": "Before Work,Difficult Day"},
        {"id": "q_peace_8", "text": "The surface of the lake reflects the mountains only when the water is perfectly still.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Peace", "situations": "Morning,Before Sleep"},
        {"id": "q_peace_9", "text": "Step into the garden at dusk. The flowers close their petals without urgency; so may you.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_peace_10", "text": "Quietness is not empty space; it is rich with the restoration your nervous system craves.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_peace_11", "text": "Breathe out the tension stored in your shoulders. Drop them down an inch.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Relieved", "situations": "Difficult Day,Before Work"},
        {"id": "q_peace_12", "text": "Peace begins within your own four walls when you refuse to harbor anger overnight.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Warm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_peace_13", "text": "A gentle voice turns the whole room into a sanctuary. Speak softly.", "author": "Stillwords", "isOriginal": True, "moods": "Gentle,Peace", "situations": "Before Work,Difficult Day"},
        {"id": "q_peace_14", "text": "Watch the glowing embers in the hearth fade into quiet ashes. Let your day gently settle.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_peace_15", "text": "The quiet pine forest asks nothing of you other than to walk beneath its green arches.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_peace_16", "text": "Do not let the world's frantic tempo become your internal rhythm.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Peace", "situations": "Before Work,Morning"},
        {"id": "q_peace_17", "text": "Rest is not a luxury you must earn; it is the rhythm by which life survives.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_peace_18", "text": "There is peace in knowing you did your honest best with the hours given to you today.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Confident", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_peace_19", "text": "Unplug the cords, darken the room, and let silence wrap you like a warm quilt.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_peace_20", "text": "A peaceful soul is an oasis in the middle of a thirsty and anxious city.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Peace", "situations": "Before Work,Morning"},
        {"id": "q_peace_21", "text": "Let go of the need to have the last word. Silence is often the most profound victory.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wise", "situations": "Difficult Day,Before Work"},
        {"id": "q_peace_22", "text": "The morning mist dissolves without struggle under the gentle heat of the rising sun.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Peace", "situations": "Morning,Starting Over"},
        {"id": "q_peace_23", "text": "Find tranquility in the simple fact that you are alive right now, breathing and here.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_peace_24", "text": "Guard your peace of mind as the most valuable asset you possess on this earth.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Peace", "situations": "Before Work,Difficult Day"},
        {"id": "q_peace_25", "text": "Listen to the slow ticking of the clock on the mantle. Time is not your enemy; it is the river carrying you home.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Thoughtful", "situations": "Before Sleep,Morning"},
        {"id": "q_peace_26", "text": "Make your mind an island of calm where chaotic waves break and gently recede.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Peace", "situations": "Difficult Day,Before Work"},
        {"id": "q_peace_27", "text": "There is a holy quietness in early dawn that belongs only to those who rise before the rush.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Wonder", "situations": "Morning,Before Work"},
        {"id": "q_peace_28", "text": "Surrender what you cannot repair tonight. Sleep will restore your sight.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_peace_29", "text": "Peace is the fragrance that remains on the hands of those who chose kindness over winning.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Peace", "situations": "Before Sleep,Before Work"}
    ],

    "Relationships": [
        {"id": "q_rela_1", "text": "A deep relationship is not built on grand gestures, but on ten thousand small moments of listening without distraction.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Warm", "situations": "Morning,Before Sleep"},
        {"id": "q_rela_2", "text": "Put your telephone in another room when you sit down for dinner. Give the gift of your undivided eyes.", "author": "Stillwords", "isOriginal": True, "moods": "Mindful,Warm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_rela_3", "text": "Listen to understand, not to draft your rebuttal while the other person is still speaking.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Calm", "situations": "Before Work,Difficult Day"},
        {"id": "q_rela_4", "text": "A healthy bond gives both people room to breathe, grow, and sometimes change their minds.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Generous", "situations": "Starting Over,Difficult Day"},
        {"id": "q_rela_5", "text": "Speak the difficult truth with honey on your tongue. Candor without compassion is just cruelty.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Gentle", "situations": "Before Work,Difficult Day"},
        {"id": "q_rela_6", "text": "The greatest gift you can offer a partner is to be a person who is at peace with themselves.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Peace", "situations": "Morning,Before Sleep"},
        {"id": "q_rela_7", "text": "Apologize without the word 'but'. An honest apology takes full ownership of the bruised ground.", "author": "Stillwords", "isOriginal": True, "moods": "Humble,Healing", "situations": "Difficult Day,Starting Over"},
        {"id": "q_rela_8", "text": "Celebrate each other's quiet victories. The world will celebrate the loud ones; be the one who notices the subtle triumphs.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Generous", "situations": "Morning,Before Sleep"},
        {"id": "q_rela_9", "text": "Trust is like fine bone china: crafted slowly through heat and care, but shattered in a careless second.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Faithful", "situations": "Before Work,Difficult Day"},
        {"id": "q_rela_10", "text": "Stand beside each other when the wind turns cold. Mutual devotion is a shelter against any winter.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Warm", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_rela_11", "text": "Make peace before your head touches the pillow. Do not carry an unresolved quarrel into the sanctuary of dreams.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Healing", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_rela_12", "text": "Give the benefit of the doubt. Most offenses are born of clumsiness or fatigue, not malice.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Calm", "situations": "Difficult Day,Before Work"},
        {"id": "q_rela_13", "text": "A good marriage is a long conversation between two people that always seems too short.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Warm", "situations": "Before Sleep,Morning"},
        {"id": "q_rela_14", "text": "Do not seek someone who completes you; look for someone with whom you can share your wholeness.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Wise", "situations": "Starting Over,Morning"},
        {"id": "q_rela_15", "text": "Protect the privacy of your partnership. Sacred ground is never meant for public broadcast.", "author": "Stillwords", "isOriginal": True, "moods": "Faithful,Noble", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_rela_16", "text": "Laugh together over burnt dinners and missed trains. Joy is finding humor in human imperfection.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Playful", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_rela_17", "text": "Hold space for your companion's sorrow without rushing to fix it. Sometimes holding a hand is the only answer.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Warm", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_rela_18", "text": "Check in on each other during the busy morning. A two-line note of affection lights up an entire workday.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Motivated", "situations": "Morning,Before Work"},
        {"id": "q_rela_19", "text": "Do not let familiarity breed contempt; let familiarity breed tenderness and reverence.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Warm", "situations": "Morning,Before Sleep"},
        {"id": "q_rela_20", "text": "When tension rises, lower your volume. Soft words possess the power to disarm boiling pride.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Wise", "situations": "Difficult Day,Before Work"},
        {"id": "q_rela_21", "text": "Remember that both of you are carrying invisible burdens. Walk gently with each other.", "author": "Stillwords", "isOriginal": True, "moods": "Gentle,Healing", "situations": "Difficult Day,Morning"},
        {"id": "q_rela_22", "text": "Shared rituals: morning coffee together, Sunday evening walks. These are the anchors of enduring affection.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Peace", "situations": "Morning,Before Sleep"},
        {"id": "q_rela_23", "text": "Forgive the small annoyances. Life is too fleeting to waste on who left the lid off the jar.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Playful", "situations": "Difficult Day,Morning"},
        {"id": "q_rela_24", "text": "Encourage your partner to pursue their deepest callings, even when it requires sacrifice.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Confident", "situations": "Before Work,Starting Over"},
        {"id": "q_rela_25", "text": "A strong relationship weather-proofs both spirits against the cold cynicism of the world.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Warm", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_rela_26", "text": "Never take for granted the warm presence beside you on the pillow. Every morning together is a grace.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Warm", "situations": "Morning,Before Sleep"},
        {"id": "q_rela_27", "text": "True intimacy is the freedom to be ordinary, tired, and quiet without fear of judgment.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_rela_28", "text": "Express gratitude out loud for the invisible chores done every day to keep the home running.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Generous", "situations": "Morning,Before Sleep"},
        {"id": "q_rela_29", "text": "Walk hand in hand when the road turns steep. Two pairs of eyes spot the stones twice as fast.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Warm", "situations": "Difficult Day,Workout"},
        {"id": "q_rela_30", "text": "Love is an enduring garden: weed it with patience, water it with kindness, and enjoy the blossoms.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Happy", "situations": "Morning,Before Sleep"}
    ],

    "Self-Love": [
        {"id": "q_self_1", "text": "Talk to yourself as if you were someone you were responsible for helping. Extend inward the same mercy you show a friend.", "author": "Stillwords", "isOriginal": True, "moods": "Gentle,Healing", "situations": "Difficult Day,Morning"},
        {"id": "q_self_2", "text": "You do not need to earn your right to rest. Rest is the soil from which all your vitality blooms.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Healing", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_self_3", "text": "Forgive yourself for the decisions you made when you were surviving on broken information and bruised courage.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Starting Over,Difficult Day"},
        {"id": "q_self_4", "text": "Set clear boundaries around your peace. A locked gate is not hatred of the outside; it is reverence for the garden within.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Peace", "situations": "Before Work,Difficult Day"},
        {"id": "q_self_5", "text": "You are allowed to be a masterpiece and a work in progress at the exact same moment.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Confident", "situations": "Morning,Starting Over"},
        {"id": "q_self_6", "text": "Stop setting yourself on fire to keep people warm who only complain about the smoke.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Confident", "situations": "Difficult Day,Before Work"},
        {"id": "q_self_7", "text": "Look at your hands. They have held grief, turned pages, cooked meals, and wiped tears. Treat them with gratitude.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Thoughtful", "situations": "Before Sleep,Morning"},
        {"id": "q_self_8", "text": "You do not have to perform your worth for the world. You belong here simply because you are alive.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Confident", "situations": "Morning,Difficult Day"},
        {"id": "q_self_9", "text": "Feed your mind with clean thoughts, your body with honest food, and your soul with unhurried silence.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Healing", "situations": "Morning,Before Sleep"},
        {"id": "q_self_10", "text": "Give yourself permission to say 'No, thank you' without offering a paragraph of defensive excuses.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Calm", "situations": "Before Work,Difficult Day"},
        {"id": "q_self_11", "text": "The way you treat yourself sets the benchmark for how the world is allowed to treat you.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Wise", "situations": "Morning,Before Work"},
        {"id": "q_self_12", "text": "Let go of the imaginary version of you that never makes mistakes. Embrace the real, breathing human being.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Starting Over,Difficult Day"},
        {"id": "q_self_13", "text": "Take yourself for a walk as if you were taking an old dear friend to see the changing leaves.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Happy", "situations": "Morning,Difficult Day"},
        {"id": "q_self_14", "text": "Your feelings are valid messengers, but you do not have to appoint every one of them as your supreme ruler.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wise", "situations": "Difficult Day,Study Time"},
        {"id": "q_self_15", "text": "Honor the quiet rhythm of your own introversion or extraversion. Inhabit your wiring with peace.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Confident", "situations": "Morning,Before Work"},
        {"id": "q_self_16", "text": "Be proud of how far you have come from the places that almost broke you.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Hopeful", "situations": "Difficult Day,Starting Over"},
        {"id": "q_self_17", "text": "Do not let social noise convince you that your quiet, simple life is not grand enough.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Before Sleep,Morning"},
        {"id": "q_self_18", "text": "Wrap yourself in a clean warm blanket and let the world spin without your intervention for one hour.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_self_19", "text": "You are worthy of the love and attention you so readily offer to others.", "author": "Stillwords", "isOriginal": True, "moods": "Gentle,Healing", "situations": "Morning,Difficult Day"},
        {"id": "q_self_20", "text": "Trust that your journey has its own wisdom, even when the fog obscures the milestones.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Hopeful", "situations": "Starting Over,Difficult Day"},
        {"id": "q_self_21", "text": "Wear clothes that feel like a gentle shelter for your body. Comfort is a form of self-respect.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Happy", "situations": "Morning,Before Work"},
        {"id": "q_self_22", "text": "Stop waiting for someone else to give you permission to be happy with your life.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Motivated", "situations": "Starting Over,Morning"},
        {"id": "q_self_23", "text": "The greatest homecoming in this life is coming home to your own skin and feeling safe there.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Healing", "situations": "Before Sleep,Morning"},
        {"id": "q_self_24", "text": "Celebrate your quirks; they are the hand-painted strokes that make you an original work of art.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Confident", "situations": "Morning,Need Confidence"},
        {"id": "q_self_25", "text": "Speak gently to the child living inside your memory who did not get what it needed back then.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Gentle", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_self_26", "text": "Your energy is sacred. Refuse to lend it to petty squabbles that leave you hollow.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Peace", "situations": "Before Work,Difficult Day"},
        {"id": "q_self_27", "text": "Drink water, sit in sunlight, and give yourself grace today.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Healing", "situations": "Morning,Difficult Day"},
        {"id": "q_self_28", "text": "You have survived 100% of your worst days so far. Give yourself the credit you deserve.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Determined", "situations": "Difficult Day,Need Confidence"},
        {"id": "q_self_29", "text": "Make your own company enjoyable by cultivating thoughts that bring light rather than gloom.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Happy", "situations": "Morning,Before Sleep"},
        {"id": "q_self_30", "text": "You are whole just as you are right now. Inhale that truth.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Healing", "situations": "Before Sleep,Morning"}
    ],

    "Study": [
        {"id": "q_40", "text": "Concentrate all your thoughts upon the work in hand. The sun's rays do not burn until brought to a focus.", "author": "Alexander Graham Bell", "isOriginal": False, "source": "Historical Papers", "moods": "Focused,Determined", "situations": "Study Time,Before Work,Need Focus"},
        {"id": "q_stud_1", "text": "Understanding is not a race against the clock; it is the quiet patience to read the same paragraph three times until the world opens up.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Calm", "situations": "Study Time,Before Work"},
        {"id": "q_stud_2", "text": "Turn the phone face down and close unnecessary tabs. Give this hour your undivided mind.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Study Time,Before Work"},
        {"id": "q_stud_3", "text": "A student who asks an earnest question learns twice as fast as the one who nods out of pride.", "author": "Stillwords", "isOriginal": True, "moods": "Humble,Motivated", "situations": "Study Time,Starting Over"},
        {"id": "q_stud_4", "text": "Sharpen your pencil, clear the desk of clutter, and invite clarity to take a seat.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Calm", "situations": "Study Time,Morning"},
        {"id": "q_stud_5", "text": "Knowledge is a library; wisdom is knowing which book to pull down when someone is weeping.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Thoughtful", "situations": "Study Time,Difficult Day"},
        {"id": "q_stud_6", "text": "Take notes by hand on clean paper. The path from ink through fingers to the brain is ancient and deep.", "author": "Stillwords", "isOriginal": True, "moods": "Mindful,Focused", "situations": "Study Time,Before Work"},
        {"id": "q_stud_7", "text": "Do not let the volume of what you do not know discourage you. Every scholar began with the alphabet.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Calm", "situations": "Study Time,Starting Over"},
        {"id": "q_stud_8", "text": "Curiosity is an unquenchable lantern. Follow its beam into difficult subjects with good cheer.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Motivated", "situations": "Study Time,Morning"},
        {"id": "q_stud_9", "text": "An hour of deep, quiet focus is worth an entire day of distracted multitasking.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Study Time,Before Work"},
        {"id": "q_stud_10", "text": "Read old books. Let thinkers who lived centuries ago challenge the blind spots of your modern era.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Wise", "situations": "Study Time,Before Sleep"},
        {"id": "q_stud_11", "text": "When a concept refuses to enter your understanding, go for a walk. The subconscious mind does its best work while walking.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wise", "situations": "Study Time,Difficult Day"},
        {"id": "q_stud_12", "text": "Treat your mind like a great library: admit only what is worthy of standing on its permanent shelves.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Noble", "situations": "Study Time,Morning"},
        {"id": "q_stud_13", "text": "The greatest test of understanding is whether you can explain the idea simply to a ten-year-old child.", "author": "Stillwords", "isOriginal": True, "moods": "Clear,Humble", "situations": "Study Time,Before Work"},
        {"id": "q_stud_14", "text": "Love the struggle of wrestling with difficult material. That tension is the brain physically growing.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Motivated", "situations": "Study Time,Difficult Day"},
        {"id": "q_stud_15", "text": "Silence is the great incubator of thought. Seek out quiet corners in libraries and old rooms.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Study Time,Before Sleep"},
        {"id": "q_stud_16", "text": "Be willing to sit with confusion without reaching for instant distraction. Answers need time to form.", "author": "Stillwords", "isOriginal": True, "moods": "Patient,Calm", "situations": "Study Time,Difficult Day"},
        {"id": "q_stud_17", "text": "Every page turned with genuine attention adds another stone to the cathedral of your understanding.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Motivated", "situations": "Study Time,Morning"},
        {"id": "q_stud_18", "text": "Highlight sparingly. If everything is emphasized, nothing is remembered.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Clear", "situations": "Study Time,Before Work"},
        {"id": "q_stud_19", "text": "Study not to impress examiners, but so you may be an informed and compassionate citizen of this earth.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Thoughtful", "situations": "Study Time,Starting Over"},
        {"id": "q_stud_20", "text": "A disciplined hour of study every morning will make you a master of any discipline within five years.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Confident", "situations": "Morning,Study Time"},
        {"id": "q_stud_21", "text": "Cherish the smell of old paper and the quiet rhythm of turning pages. Physical books carry grounded energy.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wonder", "situations": "Study Time,Before Sleep"},
        {"id": "q_stud_22", "text": "When you teach what you have learned to another, you seal the knowledge in your own soul.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Focused", "situations": "Study Time,Before Work"},
        {"id": "q_stud_23", "text": "Intellectual humility is the threshold through which every genuine scholar must step.", "author": "Stillwords", "isOriginal": True, "moods": "Humble,Wise", "situations": "Study Time,Starting Over"},
        {"id": "q_stud_24", "text": "Do not rush to memorize formulas before you have marveled at the principle behind them.", "author": "Stillwords", "isOriginal": True, "moods": "Wonder,Focused", "situations": "Study Time,Morning"},
        {"id": "q_stud_25", "text": "Rest your eyes every fifty minutes. Look out the window at green trees or distant rooftops.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Study Time,Difficult Day"},
        {"id": "q_stud_26", "text": "A curious mind never grows old. Stay a student until your final breath.", "author": "Stillwords", "isOriginal": True, "moods": "Hopeful,Motivated", "situations": "Morning,Study Time"},
        {"id": "q_stud_27", "text": "True education does not fill a pail; it ignites a hearth that burns for eighty years.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Warm", "situations": "Study Time,Starting Over"},
        {"id": "q_stud_28", "text": "Keep your notes organized and clean. Order in the notebook produces order in the intellect.", "author": "Stillwords", "isOriginal": True, "moods": "Clear,Focused", "situations": "Study Time,Before Work"},
        {"id": "q_stud_29", "text": "To study is to sit at the feet of all humanity's greatest minds across four thousand years.", "author": "Stillwords", "isOriginal": True, "moods": "Humble,Wonder", "situations": "Study Time,Before Sleep"}
    ],

    "Success": [
        {"id": "q_succ_1", "text": "True success is laying your head on the pillow at night with a clean conscience and people who love you.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Wise", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_succ_2", "text": "Do not climb the ladder of ambition only to find it was leaning against the wrong wall all along.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Wise", "situations": "Before Work,Starting Over"},
        {"id": "q_succ_3", "text": "Real triumph is building a life you do not constantly need to take a vacation from.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Morning,Before Work"},
        {"id": "q_succ_4", "text": "Success without inner peace is just well-decorated exhaustion. Guard your soul first.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Peace", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_succ_5", "text": "Mastery is doing the small, unglamorous things with flawless consistency when nobody is watching.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Before Work,Study Time"},
        {"id": "q_succ_6", "text": "Do not let the fear of striking out keep you from stepping firmly into the batter's box.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Motivated", "situations": "Need Confidence,Before Work"},
        {"id": "q_succ_7", "text": "The greatest victory over your critics is to quietly build something so honest that it cannot be denied.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Confident", "situations": "Before Work,Difficult Day"},
        {"id": "q_succ_8", "text": "A person who loves the process will always defeat someone who only loves the prize.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Motivated", "situations": "Morning,Before Work"},
        {"id": "q_succ_9", "text": "Build your house on the rock of daily integrity, not on the shifting sand of momentary applause.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Confident", "situations": "Before Work,Starting Over"},
        {"id": "q_succ_10", "text": "Measure success by how few things you need to be content, not by how many you have accumulated.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Wise", "situations": "Before Sleep,Morning"},
        {"id": "q_succ_11", "text": "When you reach the top of the ridge, reach your hand down to pull up the person behind you.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Noble", "situations": "Before Work,Morning"},
        {"id": "q_succ_12", "text": "Success is falling seven times and getting up eight with an intact sense of humor.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Happy", "situations": "Difficult Day,Starting Over"},
        {"id": "q_succ_13", "text": "Do good work every day and let the reputation take care of itself.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Focused", "situations": "Before Work,Study Time"},
        {"id": "q_succ_14", "text": "The fruit of true success is not wealth; it is freedom over your own hours and peace in your thoughts.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Wise", "situations": "Morning,Before Sleep"},
        {"id": "q_succ_15", "text": "Celebrate every small milestone along the trail. The summit is only one step of a thousand.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Hopeful", "situations": "Morning,Difficult Day"},
        {"id": "q_succ_16", "text": "Never sacrifice your health or your family on the altar of commercial success.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Determined", "situations": "Before Work,Before Sleep"},
        {"id": "q_succ_17", "text": "Patience and persistence are the quiet twin engines of every lasting triumph.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Study Time,Before Work"},
        {"id": "q_succ_18", "text": "Be reliable. In a world full of flaky promises, the person who does what they said they would do is legendary.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Faithful", "situations": "Before Work,Study Time"},
        {"id": "q_succ_19", "text": "Leave every client, reader, or colleague better off than when you first met them.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Noble", "situations": "Before Work,Morning"},
        {"id": "q_succ_20", "text": "You do not need to cut corners to succeed. The straight path is less crowded anyway.", "author": "Stillwords", "isOriginal": True, "moods": "Honorable,Confident", "situations": "Before Work,Study Time"},
        {"id": "q_succ_21", "text": "Success is turning your wound into wisdom and your struggle into service.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Noble", "situations": "Difficult Day,Starting Over"},
        {"id": "q_succ_22", "text": "Keep your overhead low and your craftsmanship high. That is the secret of independence.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Focused", "situations": "Before Work,Starting Over"},
        {"id": "q_succ_23", "text": "The greatest reward of your labor is not what you get for it, but what you become by it.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Confident", "situations": "Before Sleep,Before Work"},
        {"id": "q_succ_24", "text": "Do not let success go to your head or failure go to your heart. Stay balanced on both feet.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wise", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_succ_25", "text": "Live so that those who know you best respect you most.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Honorable", "situations": "Morning,Before Sleep"},
        {"id": "q_succ_26", "text": "Success is waking up with excitement for the work and going to sleep with satisfaction for the day.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Motivated", "situations": "Morning,Before Sleep"},
        {"id": "q_succ_27", "text": "Never compromise your honor to secure a contract. Money returns; a broken name does not.", "author": "Stillwords", "isOriginal": True, "moods": "Honorable,Determined", "situations": "Before Work,Study Time"},
        {"id": "q_succ_28", "text": "True abundance is having enough to share with someone whose cupboard is bare.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Warm", "situations": "Morning,Before Work"},
        {"id": "q_succ_29", "text": "Treat triumph and setback as two impostors of equal insignificance compared to character.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wise", "situations": "Difficult Day,Before Work"},
        {"id": "q_succ_30", "text": "A successful life is simply a string of honest, well-lived days tied together with love.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Warm", "situations": "Morning,Before Sleep"}
    ],

    "Wisdom": [
        {"id": "q_49", "text": "Dwell on the beauty of life. Watch the stars, and see yourself running with them.", "author": "Marcus Aurelius", "isOriginal": False, "source": "Meditations", "moods": "Peace,Calm,Thoughtful", "situations": "Before Sleep,Morning"},
        {"id": "q_wis_1", "text": "Wisdom is knowing what to overlook. Life is too short to engage with every provocation.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wise", "situations": "Difficult Day,Before Work"},
        {"id": "q_wis_2", "text": "The quietest man in the room often carries the heaviest cargo of understanding.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Calm", "situations": "Before Work,Study Time"},
        {"id": "q_wis_3", "text": "Do not confuse knowledge with wisdom. One is acquiring tools; the other is knowing when to leave them in the box.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Clear", "situations": "Study Time,Before Work"},
        {"id": "q_wis_4", "text": "Look at the night sky. In that immense silence, all our petty anxieties shrink to their proper size.", "author": "Stillwords", "isOriginal": True, "moods": "Wonder,Peace", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_wis_5", "text": "The river cuts through rock not because of violence, but because of patient, unyielding persistence.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Calm", "situations": "Difficult Day,Starting Over"},
        {"id": "q_wis_6", "text": "Speak only when your words are more beneficial than the silence they replace.", "author": "Stillwords", "isOriginal": True, "moods": "Wise,Peace", "situations": "Before Work,Difficult Day"},
        {"id": "q_wis_7", "text": "To be at peace with your own mortality is to receive every single morning as a priceless miracle.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Peace", "situations": "Morning,Before Sleep"},
        {"id": "q_wis_8", "text": "He who angers you conquers you. Keep your composure and keep your crown.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Confident", "situations": "Difficult Day,Before Work"},
        {"id": "q_wis_9", "text": "Listen to the counsel of old trees: dig deep roots, bend with winter gales, and offer shade freely.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_wis_10", "text": "A wise person builds bridges out of stones that other people throw at them.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Wise", "situations": "Difficult Day,Starting Over"},
        {"id": "q_wis_11", "text": "Do not cross a deep river on rumors of shallow water. Check the current with your own staff.", "author": "Stillwords", "isOriginal": True, "moods": "Cautious,Clear", "situations": "Before Work,Study Time"},
        {"id": "q_wis_12", "text": "The greatest prison you will ever inhabit is fear of what other people think of you. Walk out the door.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Relieved", "situations": "Starting Over,Need Confidence"},
        {"id": "q_wis_13", "text": "True wealth is not having overflowing barns, but having an unburdened spirit that owes nothing to vanity.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Wise", "situations": "Before Sleep,Morning"},
        {"id": "q_wis_14", "text": "Let time be your filter. What seems like an emergency at three in the afternoon is often forgotten by sunrise.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wise", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_wis_15", "text": "A clean heart and clear eyes are the two greatest compasses for any human pilgrimage.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Peace", "situations": "Morning,Starting Over"},
        {"id": "q_wis_16", "text": "Do not judge the quality of a life by its length, but by the depth of love it contained.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Warm", "situations": "Before Sleep,Difficult Day"},
        {"id": "q_wis_17", "text": "Sit with the wise in silence; their stillness will teach you more than twenty arguments.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Humble", "situations": "Study Time,Before Sleep"},
        {"id": "q_wis_18", "text": "Everything in nature yields to its proper season. Do not demand summer in the dead of January.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wise", "situations": "Difficult Day,Starting Over"},
        {"id": "q_wis_19", "text": "The tongue is a small rudder that can wreck a magnificent ship. Steer it with vigilance.", "author": "Stillwords", "isOriginal": True, "moods": "Cautious,Wise", "situations": "Before Work,Difficult Day"},
        {"id": "q_wis_20", "text": "He who knows when he has enough is rich beyond the counting of gold coins.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Wise", "situations": "Morning,Before Sleep"},
        {"id": "q_wis_21", "text": "Forgive the debts of the past. The ledger of bitterness will only poison the accountant.", "author": "Stillwords", "isOriginal": True, "moods": "Healing,Peace", "situations": "Starting Over,Difficult Day"},
        {"id": "q_wis_22", "text": "Patience is not passive waiting; it is active calm while the seeds do their invisible work.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Calm", "situations": "Study Time,Difficult Day"},
        {"id": "q_wis_23", "text": "Look upon your enemies with compassion. Hurt people hurt people; healed people bring medicine.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Wise", "situations": "Difficult Day,Before Sleep"},
        {"id": "q_wis_24", "text": "The greatest wisdom is to remain gentle in a world that prides itself on hardness.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Peace", "situations": "Morning,Difficult Day"},
        {"id": "q_wis_25", "text": "Do not measure your worth by the applause of a crowd that will forget you by twilight.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Wise", "situations": "Before Work,Before Sleep"},
        {"id": "q_wis_26", "text": "Hold onto what is good with a steady grip, and release the rest without rancor.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Before Sleep,Starting Over"},
        {"id": "q_wis_27", "text": "The stars do not compete with one another; each shines in its assigned quadrant of the night.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Wonder", "situations": "Before Sleep,Morning"},
        {"id": "q_wis_28", "text": "A wise person finds a teacher in every experience, even in painful ones.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Hopeful", "situations": "Difficult Day,Starting Over"},
        {"id": "q_wis_29", "text": "Live simply, speak honestly, and leave a trail of gentle peace wherever your boots tread.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Peace", "situations": "Morning,Before Sleep"}
    ],

    "Work": [
        {"id": "q_work_1", "text": "Craftsmanship is love made visible in wood, stone, ink, or code.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Motivated", "situations": "Before Work,Study Time"},
        {"id": "q_work_2", "text": "Do not rush the joint that holds the roof up. Take the extra hour to make it true.", "author": "Stillwords", "isOriginal": True, "moods": "Patient,Focused", "situations": "Before Work,Study Time"},
        {"id": "q_work_3", "text": "Work with clean hands and a steady heart. The work you leave behind is your signature on reality.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Determined", "situations": "Morning,Before Work"},
        {"id": "q_work_4", "text": "Sweep the floor of your shop as if an emperor were visiting. Dignity lives in every square inch.", "author": "Stillwords", "isOriginal": True, "moods": "Humble,Focused", "situations": "Morning,Before Work"},
        {"id": "q_work_5", "text": "Clear the table of distractions. One clear task tackled with full focus will move mountains.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Before Work,Study Time"},
        {"id": "q_work_6", "text": "Do not let haste ruin what patience was meant to perfect.", "author": "Stillwords", "isOriginal": True, "moods": "Calm,Wise", "situations": "Before Work,Study Time"},
        {"id": "q_work_7", "text": "Honest labor sweetens the evening crust of bread and softens the nighttime pillow.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Peace", "situations": "Before Sleep,Before Work"},
        {"id": "q_work_8", "text": "Take pride in the invisible infrastructure you build that nobody will ever notice until it fails.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Focused", "situations": "Before Work,Study Time"},
        {"id": "q_work_9", "text": "Show up on time, speak plainly, and deliver what you promised. That is nine-tenths of genius.", "author": "Stillwords", "isOriginal": True, "moods": "Confident,Faithful", "situations": "Before Work,Study Time"},
        {"id": "q_work_10", "text": "Treat your tools with care. A sharp chisel saves the carpenter an entire afternoon of bruised timber.", "author": "Stillwords", "isOriginal": True, "moods": "Careful,Focused", "situations": "Before Work,Study Time"},
        {"id": "q_work_11", "text": "Let your work be an offering to the common good, not just a transaction for survival.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Generous", "situations": "Morning,Before Work"},
        {"id": "q_work_12", "text": "Do not complain about the grain of the wood. The master woodworker adapts the chisel to the knot.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Wise", "situations": "Difficult Day,Before Work"},
        {"id": "q_work_13", "text": "A difficult problem yields to patient dismantling piece by piece. Start with the easiest bolt.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Calm", "situations": "Study Time,Before Work"},
        {"id": "q_work_14", "text": "Rest when the job is done, but never while your hand is on the plow.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Motivated", "situations": "Before Work,Workout"},
        {"id": "q_work_15", "text": "Find quiet pleasure in the smell of sawdust, the hum of the engine, the tap of keys.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Mindful", "situations": "Before Work,Morning"},
        {"id": "q_work_16", "text": "When you build something solid, you leave an anchor in the storm for someone who comes after you.", "author": "Stillwords", "isOriginal": True, "moods": "Thoughtful,Noble", "situations": "Before Work,Study Time"},
        {"id": "q_work_17", "text": "Never compromise on safety or truth to speed up delivery.", "author": "Stillwords", "isOriginal": True, "moods": "Honorable,Determined", "situations": "Before Work,Study Time"},
        {"id": "q_work_18", "text": "The artisan's highest reward is standing back at sunset and knowing: 'I built that with care.'", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Peace", "situations": "Before Sleep,Before Work"},
        {"id": "q_work_19", "text": "Do not let commercial pressure extinguish the artistic soul of your labor.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Confident", "situations": "Before Work,Study Time"},
        {"id": "q_work_20", "text": "Work side by side with good people. Shared toil builds bonds that time cannot corrode.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Motivated", "situations": "Before Work,Morning"},
        {"id": "q_work_21", "text": "Every profession is honorable when practiced with clean motives and deep attention.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Humble", "situations": "Morning,Before Work"},
        {"id": "q_work_22", "text": "Learn the fundamentals backwards and forwards. True freedom in craft begins with mastery of basics.", "author": "Stillwords", "isOriginal": True, "moods": "Focused,Determined", "situations": "Study Time,Before Work"},
        {"id": "q_work_23", "text": "A day of honest labor brings a night of deep, untroubled slumber.", "author": "Stillwords", "isOriginal": True, "moods": "Peace,Calm", "situations": "Before Sleep,Before Work"},
        {"id": "q_work_24", "text": "Treat your coworkers with gentle dignity, especially on the days when deadlines pinch.", "author": "Stillwords", "isOriginal": True, "moods": "Warm,Wise", "situations": "Before Work,Difficult Day"},
        {"id": "q_work_25", "text": "Do not leave a job half-done. Finish the row so tomorrow's sunrise greets an open field.", "author": "Stillwords", "isOriginal": True, "moods": "Determined,Focused", "situations": "Before Work,Before Sleep"},
        {"id": "q_work_26", "text": "The greatest tribute to your trade is teaching its secrets to the next generation.", "author": "Stillwords", "isOriginal": True, "moods": "Generous,Noble", "situations": "Study Time,Before Work"},
        {"id": "q_work_27", "text": "Work with joy. Bitterness in labor poisons both the maker and the object made.", "author": "Stillwords", "isOriginal": True, "moods": "Happy,Peace", "situations": "Morning,Before Work"},
        {"id": "q_work_28", "text": "Measure twice, cut once: that is the golden rule of carpentry and human speech alike.", "author": "Stillwords", "isOriginal": True, "moods": "Careful,Wise", "situations": "Before Work,Study Time"},
        {"id": "q_work_29", "text": "A well-crafted life is your greatest masterpiece. Give it your highest craftsmanship.", "author": "Stillwords", "isOriginal": True, "moods": "Noble,Thoughtful", "situations": "Morning,Before Sleep"},
        {"id": "q_work_30", "text": "Put your hand to the work with gladness today. You have an opportunity to leave the world better.", "author": "Stillwords", "isOriginal": True, "moods": "Motivated,Happy", "situations": "Morning,Before Work"}
    ]
}
